-- 1) Snapshot the instructions of bucket GIFs that move to another exercise.
create temp table _copy_instr on commit drop as
select v.dst, e.instructions_en, e.instructions_es
from (values
  ('patada de glúteo en polea (donkey kick)', 'patada de glúteo en 4 apoyos (fire hydrant)'),
  ('press arnold', 'press de hombro con mancuernas'),
  ('remo inclinado con barra (barbell row)', 'remo a dos manos')
) as v(dst, src)
join public.exercises e on lower(e.name) = v.src;

