do $$
declare r record;
begin
  for r in
    select c.conrelid::regclass as tbl, a.attname as col
      from pg_constraint c
      join pg_attribute a on a.attrelid = c.conrelid and a.attnum = any (c.conkey)
     where c.contype = 'f' and c.confrelid = 'public.exercises'::regclass
  loop
    execute format(
      'update %s t set %I = d.id
         from _merge m
         join public.exercises s on lower(s.name) = m.src
         join public.exercises d on lower(d.name) = m.dst
        where t.%I = s.id', r.tbl, r.col, r.col);
  end loop;
end $$;

delete from public.exercises e using _merge m where lower(e.name) = m.src;

-- 3) Test entry: delete it unless something references it.
do $$
declare r record; used boolean := false; v_id uuid;
begin
  select id into v_id from public.exercises where lower(name) = 'tu';
  for r in
    select c.conrelid::regclass as tbl, a.attname as col
      from pg_constraint c
      join pg_attribute a on a.attrelid = c.conrelid and a.attnum = any (c.conkey)
     where c.contype = 'f' and c.confrelid = 'public.exercises'::regclass
  loop
    execute format('select exists (select 1 from %s where %I = $1)', r.tbl, r.col) into used using v_id;
    exit when used;
  end loop;
  if used then
    update public.exercises set video_url = null, updated_at = now() where id = v_id;
    raise notice 'Exercise "tu" is in use: kept, video removed.';
  else
    delete from public.exercises where id = v_id;
  end if;
end $$;

-- 4) New GIF, new name and matching instructions.
update public.exercises e set
  name = coalesce(v.new_name, e.name),
  video_url = 'https://rzgwkwxskrovxnnymxqo.supabase.co/storage/v1/object/public/exercise-media/' || v.file,
  instructions_en = coalesce(v.en::jsonb, c.instructions_en, e.instructions_en),
  instructions_es = coalesce(v.es::jsonb, c.instructions_es, e.instructions_es),
  updated_at = now()
from (values
  ('bicicleta', 'stationary-bike-run-v-3.gif', null::text, '["Adjust the seat height and position to ensure proper alignment.", "Place your feet on the pedals and secure them with the straps if available.", "Start pedaling at a comfortable pace.", "Maintain a steady rhythm and increase the resistance as desired.", "Engage your core muscles to maintain stability and proper posture.", "Continue pedaling for the desired duration of your workout.", "Gradually decrease the resistance and slow down before coming to a complete stop.", "Stretch your legs and cool down after the workout."]', '["Ajusta la altura del sillín de la bicicleta estática.", "Coloca los pies en los pedales.", "Empieza a pedalear a un ritmo cómodo.", "Puedes pedalear de pie, como en la imagen, o sentado.", "Ajusta la resistencia según el entrenamiento.", "Reduce el ritmo poco a poco antes de terminar."]'),
  ('clean (levantamiento)', 'power-clean.gif', null::text, '["Start with the barbell on the ground in front of you, with your feet shoulder-width apart.", "Bend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Keep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees.", "As the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.", "As the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position.", "Stand up with the barbell, fully extending your hips and knees.", "Lower the barbell back down to the starting position, keeping control of the weight throughout the movement.", "Repeat for the desired number of repetitions."]', '["Colócate con la barra en el suelo frente a ti y los pies a la anchura de los hombros.", "Agáchate y sujeta la barra con agarre prono, un poco más abierto que los hombros.", "Con la espalda recta y el pecho arriba, levanta la barra extendiendo cadera y rodillas.", "Al pasar las rodillas, extiende la cadera de forma explosiva y tira de la barra hacia arriba con los codos altos.", "Métete debajo de la barra y recíbela sobre los hombros con los codos hacia delante.", "Ponte de pie por completo y baja la barra con control.", "Repite el número de repeticiones deseado."]'),
  ('correr en la cinta', 'run-equipment.gif', null::text, '["Step onto the treadmill and start walking at a low speed.", "Increase the speed to a comfortable running pace.", "Keep your torso upright, arms bent and eyes forward.", "Land softly and keep a steady rhythm.", "Gradually reduce the speed before stepping off."]', '["Sube a la cinta y empieza caminando a velocidad baja.", "Aumenta la velocidad hasta un ritmo de carrera cómodo.", "Mantén el torso erguido, los brazos flexionados y la mirada al frente.", "Pisa de forma suave y mantén un ritmo constante.", "Reduce la velocidad poco a poco antes de bajarte."]'),
  ('cruces en polea alta', 'cable-standing-fly.gif', null::text, '["Attach the handles to the high pulleys.", "Stand between the pulleys with your feet shoulder-width apart.", "Hold the handles with your arms raised out to the sides.", "Keep your core engaged and your back straight.", "With a slight bend in your elbows, bring your arms down and forward until your hands meet in front of your hips.", "Squeeze your chest at the end of the movement.", "Slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca los agarres en las poleas altas.", "Ponte de pie entre las poleas con los pies a la anchura de los hombros.", "Sujeta los agarres con los brazos abiertos y elevados a los lados.", "Mantén el core activo y la espalda recta.", "Con los codos ligeramente flexionados, lleva los brazos hacia abajo y hacia delante hasta juntarlos frente a la cadera.", "Contrae el pecho al final del movimiento.", "Vuelve lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('cruces en polea baja', 'cable-low-fly.gif', null::text, '["Attach the handles to the low pulleys of a cable machine and select an appropriate weight.", "Stand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees.", "Grasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows.", "Maintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body.", "Pause for a moment at the peak of the movement, feeling the stretch in your chest muscles.", "Reverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout.", "Repeat for the desired number of repetitions."]', '["Coloca los agarres en las poleas bajas y elige el peso.", "Ponte de pie en el centro de la máquina con los pies a la anchura de los hombros.", "Sujeta los agarres con los brazos abiertos a los lados y los codos ligeramente flexionados.", "Lleva los brazos hacia delante y hacia arriba en un arco, juntándolos frente al pecho.", "Haz una breve pausa contrayendo el pecho.", "Vuelve lentamente a la posición inicial manteniendo la tensión.", "Repite el número de repeticiones deseado."]'),
  ('cruces en polea media', 'cable-middle-fly.gif', null::text, '["Attach cables to both sides of a cable machine at chest height.", "Stand in the center of the machine with one foot slightly in front of the other.", "Grasp the handles with an overhand grip and extend your arms out to the sides.", "Keep a slight bend in your elbows and maintain a slight forward lean.", "Engage your chest muscles and bring your arms forward in a sweeping motion.", "Pause for a moment at the center, then slowly return your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca los agarres de ambas poleas a la altura del pecho.", "Ponte de pie en el centro con un pie ligeramente adelantado.", "Sujeta los agarres con los brazos abiertos a los lados.", "Con los codos ligeramente flexionados, junta los brazos frente al pecho en un arco horizontal.", "Haz una breve pausa en el centro y vuelve lentamente.", "Repite el número de repeticiones deseado."]'),
  ('curl de bíceps con agarre cruzado', 'dumbbell-cross-body-hammer-curl.gif', null::text, '["Stand up straight with a dumbbell in each hand, palms facing your body.", "Keep your elbows close to your torso and your upper arms stationary.", "Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con una mancuerna en cada mano, palmas hacia el cuerpo.", "Mantén los codos pegados al torso.", "Flexiona el codo y lleva la mancuerna cruzando el cuerpo hacia el hombro contrario.", "Haz una breve pausa arriba contrayendo el bíceps.", "Baja lentamente y alterna los brazos.", "Repite el número de repeticiones deseado."]'),
  ('curl de bíceps con agarre neutro (martillo)', 'dumbbell-hammer-curl.gif', null::text, '["Stand up straight with a dumbbell in each hand, palms facing each other (hammer grip).", "Keep your elbows close to your torso and your upper arms stationary.", "Bend your elbows and curl the dumbbells up without rotating your wrists.", "Lift to shoulder height and pause briefly.", "Slowly lower back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con una mancuerna en cada mano y las palmas enfrentadas (agarre martillo).", "Mantén los codos pegados al torso y la parte superior de los brazos inmóvil.", "Flexiona los codos y sube las mancuernas sin girar las muñecas.", "Sube hasta la altura de los hombros y haz una breve pausa.", "Baja lentamente hasta la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('curl de bíceps con agarre prono (inverso)', 'barbell-reverse-curl.gif', null::text, '["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.", "Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.", "Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies a la anchura de los hombros y sujeta la barra con agarre prono (palmas hacia abajo).", "Sin mover la parte superior de los brazos, flexiona los codos y sube la barra.", "Sube hasta que la barra llegue a la altura de los hombros.", "Haz una breve pausa contrayendo los brazos.", "Baja la barra lentamente hasta la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('curl de muñeca con mancuerna', 'dumbbell-seated-palms-up-wrist-curl.gif', null::text, '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.", "Rest your forearms on your thighs, allowing your wrists to hang off the edge.", "Slowly curl your wrists upward, squeezing your forearms at the top of the movement.", "Pause for a moment, then lower your wrists back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con una mancuerna en cada mano, palmas hacia arriba.", "Apoya los antebrazos sobre los muslos dejando las muñecas fuera de las rodillas.", "Flexiona las muñecas hacia arriba contrayendo los antebrazos.", "Haz una breve pausa y baja lentamente.", "Repite el número de repeticiones deseado."]'),
  ('curl de muñeca inverso', 'barbell-reverse-wrist-curl.gif', null::text, '["Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.", "Rest your forearms on your thighs, allowing your wrists to hang off the edge.", "Slowly curl your wrists upward, bringing the barbell towards your body.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco y sujeta la barra con agarre prono (palmas hacia abajo).", "Apoya los antebrazos sobre los muslos dejando las muñecas fuera de las rodillas.", "Extiende las muñecas hacia arriba levantando la barra.", "Haz una breve pausa arriba y baja lentamente.", "Repite el número de repeticiones deseado."]'),
  ('dead bug', 'dead-bug.gif', null::text, '["Lie flat on your back with your arms extended towards the ceiling.", "Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.", "Engage your core and lower back to press your lower back into the ground.", "Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor.", "Pause for a moment, then return to the starting position.", "Repeat the movement with your left arm and right leg.", "Continue alternating sides for the desired number of repetitions."]', '["Túmbate boca arriba con los brazos extendidos hacia el techo.", "Levanta las piernas con caderas y rodillas a 90 grados.", "Activa el core y presiona la zona lumbar contra el suelo.", "Baja lentamente el brazo derecho y la pierna izquierda hasta casi tocar el suelo.", "Vuelve a la posición inicial.", "Repite con el brazo izquierdo y la pierna derecha.", "Alterna los lados hasta completar las repeticiones."]'),
  ('dominadas con agarre neutro', 'pull-up-neutral-grip.gif', null::text, '["Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.", "Engage your core and squeeze your shoulder blades together.", "Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position with control.", "Repeat for the desired number of repetitions."]', '["Cuélgate de la barra con agarre neutro (palmas enfrentadas) y los brazos extendidos.", "Activa el core y junta los omóplatos.", "Tira del cuerpo hacia arriba llevando los codos hacia la cadera.", "Sube hasta que la barbilla pase la barra.", "Baja lentamente hasta extender los brazos.", "Repite el número de repeticiones deseado."]'),
  ('dominadas con agarre prono (front)', 'pull-up.gif', null::text, '["Hang from a pull-up bar with your palms facing away from you and your arms fully extended.", "Engage your core and squeeze your shoulder blades together.", "Pull your body up towards the bar by bending your elbows and bringing your chest towards the bar.", "Pause at the top of the movement, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de la barra con agarre prono (palmas hacia delante) y los brazos extendidos.", "Activa el core y junta los omóplatos.", "Tira del cuerpo hacia arriba llevando el pecho hacia la barra.", "Haz una breve pausa arriba y baja lentamente.", "Repite el número de repeticiones deseado."]'),
  ('dominadas con agarre supino (rear)', 'chin-up.gif', null::text, '["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.", "Engage your core and pull your body up towards the bar, leading with your chest.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de la barra con agarre supino (palmas hacia ti) a la anchura de los hombros.", "Activa el core y tira del cuerpo hacia arriba.", "Sube hasta que la barbilla pase la barra.", "Haz una breve pausa arriba y baja lentamente.", "Repite el número de repeticiones deseado."]'),
  ('elevaciones de rodillas', 'hanging-leg-raise.gif', null::text, '["Hang from a pull-up bar with your arms fully extended and palms facing forward.", "Engage your core and raise your bent knees towards your chest.", "Lift until your thighs are at least parallel to the floor.", "Pause, then lower your legs slowly without swinging.", "Repeat for the desired number of repetitions."]', '["Cuélgate de una barra con los brazos extendidos y las palmas hacia delante.", "Activa el core y sube las rodillas flexionadas hacia el pecho.", "Sube hasta que los muslos queden al menos paralelos al suelo.", "Haz una breve pausa y baja las piernas lentamente, sin balancearte.", "Repite el número de repeticiones deseado."]'),
  ('elevaciones laterales inclinado', 'dumbbell-incline-one-arm-lateral-raise.gif', null::text, '["Lie on your side on an incline bench, chest facing away from the bench.", "Hold a dumbbell in your top hand in front of your thigh.", "With a slight bend in your elbow, raise the dumbbell towards the ceiling.", "Pause at the top, then lower slowly.", "Complete the repetitions, then switch arms."]', '["Túmbate de lado sobre un banco inclinado, con el pecho mirando hacia fuera.", "Sujeta una mancuerna con el brazo de arriba, apoyada frente al muslo.", "Con el codo ligeramente flexionado, eleva la mancuerna hacia el techo.", "Haz una breve pausa arriba y baja lentamente.", "Completa las repeticiones y cambia de brazo."]'),
  ('elevación de gemelos con déficit', 'lever-standing-calf-raise.gif', 'Elevación de Gemelos de Pie en Máquina', null::text, null::text),
  ('elevación de gemelos de pie a 1 pierna', 'dumbbell-single-leg-calf-raise.gif', null::text, '["Stand on the edge of a step or platform with your heels hanging off and your toes on the step.", "Hold a dumbbell in one hand and place your other hand on a wall or railing for support.", "Raise your heel as high as possible, lifting your body up onto your toes.", "Pause for a moment at the top, then slowly lower your heel back down below the step.", "Repeat for the desired number of repetitions, then switch to the other leg."]', '["Ponte de pie sobre una pierna con una mancuerna en la mano del mismo lado.", "Apoya la otra mano en una pared o soporte para mantener el equilibrio.", "Eleva el talón lo más alto posible, subiendo sobre la punta del pie.", "Haz una breve pausa arriba y baja lentamente.", "Completa las repeticiones y cambia de pierna."]'),
  ('elevación de gemelos en prensa de piernas', 'sled-calf-press-on-leg-press.gif', null::text, '["Sit in the leg press with your back against the pad.", "Place the balls of your feet on the lower edge of the platform, shoulder-width apart.", "With your knees extended, push the platform with the balls of your feet.", "Pause at the top, then slowly let your heels come back down.", "Repeat for the desired number of repetitions."]', '["Siéntate en la prensa de piernas con la espalda apoyada.", "Coloca la punta de los pies en el borde inferior de la plataforma, a la anchura de los hombros.", "Con las rodillas extendidas, empuja la plataforma con la punta de los pies.", "Haz una breve pausa arriba y deja bajar los talones lentamente.", "Repite el número de repeticiones deseado."]'),
  ('elevación de pierna lateral (side-lying leg raise)', 'side-hip-abduction.gif', null::text, '["Lie on your side with your legs extended and rest your head on your lower arm.", "Place your other hand on the floor in front of your chest for stability.", "Raise your top leg straight up without rotating your hips.", "Pause at the top, then lower it slowly.", "Complete the repetitions, then switch sides."]', '["Túmbate de lado con las piernas extendidas y apoya la cabeza en el brazo de abajo.", "Coloca la otra mano en el suelo frente al pecho para estabilizarte.", "Eleva la pierna de arriba recta, sin girar la cadera.", "Haz una breve pausa arriba y bájala lentamente.", "Completa las repeticiones y cambia de lado."]'),
  ('elevación de piernas colgado (hanging leg raise)', 'hanging-straight-leg-raise.gif', null::text, '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your legs up in front of you, keeping them straight.", "Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de una barra con los brazos extendidos y las palmas hacia delante.", "Activa el core y eleva las piernas rectas por delante del cuerpo.", "Sube hasta que las piernas queden paralelas al suelo o lo más alto que puedas.", "Haz una breve pausa y baja las piernas lentamente, sin balancearte.", "Repite el número de repeticiones deseado."]'),
  ('elevación de piernas en banco (decline leg raise)', 'lying-leg-raise-flat-bench.gif', 'Elevación de Piernas en Banco (Lying Leg Raise)', '["Lie flat on a flat bench with your back pressed against it.", "Place your hands under your glutes for support.", "Keep your legs straight and together, and lift them up towards the ceiling.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba sobre un banco plano.", "Coloca las manos debajo de los glúteos o sujeta el banco.", "Con las piernas rectas y juntas, elévalas hacia el techo.", "Haz una breve pausa arriba y bájalas lentamente sin tocar el banco.", "Repite el número de repeticiones deseado."]'),
  ('encogimientos detrás de la espalda', 'smith-back-shrug.gif', null::text, '["Stand in a Smith machine with your back to the bar.", "Grab the bar behind your thighs with an overhand grip.", "With your arms straight, lift your shoulders towards your ears.", "Squeeze your traps, pause, then lower slowly.", "Repeat for the desired number of repetitions."]', '["Colócate en la máquina Smith de espaldas a la barra.", "Sujeta la barra por detrás de los muslos con agarre prono.", "Con los brazos extendidos, eleva los hombros hacia las orejas.", "Contrae los trapecios, haz una breve pausa y baja lentamente.", "Repite el número de repeticiones deseado."]'),
  ('extensiones de tríceps a 1 brazo en polea', 'cable-one-arm-tricep-pushdown.gif', null::text, '["Attach a single handle to the high pulley.", "Stand facing the machine and grab the handle with one hand.", "Keep your elbow against your side, bent at 90 degrees.", "Keeping your upper arm still, push down until your elbow is fully extended.", "Pause, then return slowly.", "Complete the repetitions, then switch arms."]', '["Coloca un agarre individual en la polea alta.", "Ponte de pie frente a la máquina y sujeta el agarre con una mano.", "Pega el codo al cuerpo, flexionado a 90 grados.", "Sin mover la parte superior del brazo, empuja hacia abajo hasta extender el codo.", "Haz una breve pausa y vuelve lentamente.", "Completa las repeticiones y cambia de brazo."]'),
  ('extensiones de tríceps en banco inclinado', 'ez-barbell-incline-triceps-extension.gif', null::text, '["Set up an incline bench at a 45-degree angle.", "Sit on the bench with your back against the pad and hold the ez barbell with an overhand grip.", "Extend your arms fully overhead, keeping your elbows close to your head.", "Lower the barbell behind your head by bending your elbows, keeping your upper arms stationary.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta un banco inclinado a unos 45 grados y siéntate con la espalda apoyada.", "Sujeta la barra Z con agarre prono y extiende los brazos por encima de la cabeza.", "Mantén los codos cerca de la cabeza.", "Flexiona los codos y baja la barra por detrás de la cabeza sin mover la parte superior de los brazos.", "Haz una breve pausa y extiende los brazos de nuevo.", "Repite el número de repeticiones deseado."]'),
  ('extensiones de tríceps en banco plano (skull crusher)', 'barbell-lying-triceps-extension-skull-crusher.gif', null::text, '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.", "Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.", "Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco plano con los pies apoyados en el suelo.", "Sujeta la barra con agarre prono a la anchura de los hombros y extiende los brazos sobre el pecho.", "Sin mover la parte superior de los brazos, flexiona los codos y baja la barra hacia la frente.", "Haz una breve pausa justo encima de la frente y extiende los brazos de nuevo.", "Repite el número de repeticiones deseado."]'),
  ('extensiones de tríceps en máquina', 'lever-triceps-extension.gif', null::text, '["Adjust the seat and sit with the back of your upper arms on the pad.", "Grab the handles with your elbows bent.", "Extend your elbows, pushing the handles until your arms are straight.", "Pause, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta el asiento y siéntate con la parte posterior de los brazos apoyada en la almohadilla.", "Sujeta los agarres con los codos flexionados.", "Extiende los codos empujando los agarres hasta estirar los brazos.", "Haz una breve pausa y vuelve lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('extensiones de tríceps en polea invertido', 'cable-reverse-grip-pushdown.gif', null::text, '["Attach a straight bar to a high pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted.", "Pause for a moment, then slowly return the bar to the starting position.", "Repeat for the desired number of repetitions."]', '["Engancha una barra recta en la polea alta.", "Ponte de pie frente a la máquina con los pies a la anchura de los hombros.", "Sujeta la barra con agarre supino (palmas hacia arriba) a la anchura de los hombros.", "Mantén los codos pegados al cuerpo y la parte superior de los brazos inmóvil.", "Empuja la barra hacia abajo hasta extender los brazos por completo.", "Haz una breve pausa y vuelve lentamente.", "Repite el número de repeticiones deseado."]'),
  ('extensiones de tríceps por encima de la cabeza', 'dumbbell-standing-triceps-extension.gif', null::text, '["Stand and hold one dumbbell with both hands above your head.", "Keep your elbows close to your head.", "Bend your elbows and lower the dumbbell behind your head without moving your upper arms.", "Extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie y sujeta una mancuerna con ambas manos por encima de la cabeza.", "Mantén los codos cerca de la cabeza.", "Flexiona los codos y baja la mancuerna por detrás de la cabeza sin mover la parte superior de los brazos.", "Extiende los brazos de nuevo hasta la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('face pull (deltoides posterior + manguito)', 'cable-standing-rear-delt-row-with-rope.gif', null::text, '["Attach a rope to a cable pulley at face height.", "Hold the rope with both hands, palms facing each other, and step back to create tension.", "Keep your back straight and your core engaged.", "Pull the rope towards your face, separating your hands and driving your elbows high and back.", "Squeeze your shoulder blades, pause, then slowly return.", "Repeat for the desired number of repetitions."]', '["Engancha una cuerda en la polea a la altura de la cara.", "Sujeta la cuerda con ambas manos, palmas enfrentadas, y da un paso atrás para tensar el cable.", "Mantén la espalda recta y el core activo.", "Tira de la cuerda hacia la cara separando las manos y llevando los codos altos y hacia atrás.", "Junta los omóplatos, haz una breve pausa y vuelve lentamente.", "Repite el número de repeticiones deseado."]'),
  ('flexiones de brazos', 'push-up.gif', null::text, '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.", "Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line.", "Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Colócate en plancha alta con las manos un poco más abiertas que los hombros.", "Activa el core y baja el cuerpo flexionando los codos, manteniéndolo en línea recta.", "Baja hasta que el pecho quede cerca del suelo.", "Empuja hasta extender los brazos.", "Repite el número de repeticiones deseado."]'),
  ('flexión de dedos con goma', 'band-wrist-curl.gif', 'Curl de Muñeca con Goma Elástica', null::text, null::text),
  ('fondos asistidos', 'assisted-triceps-dip-kneeling.gif', null::text, '["Adjust the machine to your desired weight and height.", "Kneel down on the pad facing the machine, with your hands gripping the handles.", "Lower your body by bending your elbows, keeping your back straight and close to the machine.", "Pause for a moment at the bottom, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta el peso de asistencia de la máquina.", "Arrodíllate sobre la almohadilla de frente a la máquina y sujeta las asas.", "Baja el cuerpo flexionando los codos, con la espalda recta y cerca de la máquina.", "Haz una breve pausa abajo y empuja hasta extender los brazos.", "Repite el número de repeticiones deseado."]'),
  ('fondos de tríceps', 'triceps-dip.gif', null::text, '["Support yourself on parallel bars with your arms extended and torso upright.", "Keep your elbows close to your body.", "Bend your elbows and lower your body vertically until your arms are at about 90 degrees.", "Push back up until your arms are straight.", "Repeat for the desired number of repetitions."]', '["Sujétate en las barras paralelas con los brazos extendidos y el torso erguido.", "Mantén los codos cerca del cuerpo.", "Flexiona los codos y baja el cuerpo en vertical hasta que los brazos formen unos 90 grados.", "Empuja hasta extender los brazos.", "Repite el número de repeticiones deseado."]'),
  ('fondos en anillas', 'ring-dips.gif', null::text, '["Support yourself on the rings with your arms extended and your body straight.", "Bend your elbows and lower until your shoulders are below your elbows.", "Keep the rings close to your body.", "Push back up until your arms are straight.", "Repeat for the desired number of repetitions."]', '["Sujétate en las anillas con los brazos extendidos y el cuerpo recto.", "Flexiona los codos y baja hasta que los hombros queden por debajo de los codos.", "Mantén las anillas cerca del cuerpo.", "Empuja hasta extender los brazos y volver arriba.", "Repite el número de repeticiones deseado."]'),
  ('fondos en banco (tríceps)', 'bench-dip-knees-bent.gif', null::text, '["Sit on the edge of a bench and grip it next to your hips.", "Slide your hips off the bench with your knees bent and feet flat on the floor.", "Bend your elbows and lower your body, keeping your back close to the bench.", "Pause at the bottom, then push back up until your arms are straight.", "Repeat for the desired number of repetitions."]', '["Siéntate en el borde de un banco y sujeta el borde con las manos junto a la cadera.", "Desliza la cadera fuera del banco con las rodillas flexionadas y los pies apoyados en el suelo.", "Flexiona los codos y baja el cuerpo manteniendo la espalda cerca del banco.", "Haz una breve pausa abajo y empuja hasta extender los brazos.", "Repite el número de repeticiones deseado."]'),
  ('fondos en paralelas', 'chest-dip.gif', null::text, '["Position yourself on parallel bars with your arms fully extended and your body straight.", "Lower your body by bending your elbows until your shoulders are below your elbows.", "Push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Sujétate en las barras paralelas con los brazos extendidos.", "Inclina ligeramente el torso hacia delante.", "Flexiona los codos y baja hasta que los hombros queden por debajo de los codos.", "Empuja hasta extender los brazos y volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('giro con cable (cable woodchop)', 'cable-twist-up-down.gif', null::text, '["Attach a handle to the high pulley and stand sideways to the machine.", "Hold the handle with both hands above the shoulder closest to the pulley.", "Engage your core and pull diagonally down, rotating your torso towards the opposite hip.", "Pivot on your back foot to follow the movement.", "Slowly return to the starting position.", "Complete the repetitions, then switch sides."]', '["Coloca un agarre en la polea alta y ponte de lado a la máquina.", "Sujeta el agarre con ambas manos por encima del hombro más cercano a la polea.", "Activa el core y tira en diagonal hacia abajo, girando el torso hasta la cadera contraria.", "Gira sobre el pie trasero acompañando el movimiento.", "Vuelve lentamente a la posición inicial.", "Completa las repeticiones y cambia de lado."]'),
  ('giros rusos (russian twist)', 'russian-twist.gif', null::text, '["Sit on the ground with your knees bent and feet flat on the floor.", "Lean back slightly while keeping your back straight and your core engaged.", "Hold your hands together in front of your chest or hold a weight if desired.", "Lift your feet off the ground, balancing on your sit bones.", "Twist your torso to the right, bringing your hands or weight towards the right side of your body.", "Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.", "Continue alternating sides for the desired number of repetitions."]', '["Siéntate en el suelo con las rodillas flexionadas.", "Inclina el torso hacia atrás con la espalda recta y el core activo.", "Junta las manos frente al pecho y despega los pies del suelo.", "Gira el torso hacia un lado llevando las manos junto a la cadera.", "Gira hacia el otro lado.", "Alterna los lados hasta completar las repeticiones."]'),
  ('glute bridge (puente de glúteo en suelo)', 'low-glute-bridge-on-floor.gif', null::text, '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your arms by your sides, palms facing down.", "Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.", "Pause for a moment at the top, squeezing your glutes.", "Slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca los brazos a los lados con las palmas hacia abajo.", "Activa glúteos y core y eleva la cadera hasta alinear rodillas, cadera y hombros.", "Contrae los glúteos arriba, haz una breve pausa y baja lentamente.", "Repite el número de repeticiones deseado."]'),
  ('glute bridge unilateral', 'single-leg-bridge-with-outstretched-leg.gif', null::text, '["Lie on your back with your knees bent and feet flat on the ground.", "Extend one leg straight out in front of you.", "Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.", "Hold for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions, then switch legs."]', '["Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.", "Extiende una pierna en el aire.", "Empuja con el pie apoyado y eleva la cadera hasta alinear rodilla, cadera y hombros.", "Haz una breve pausa arriba y baja lentamente.", "Completa las repeticiones y cambia de pierna."]'),
  ('hiperextensiones en banco (back extension)', 'hyperextension-on-bench.gif', null::text, '["Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.", "Cross your arms over your chest or place your hands behind your head.", "Slowly lower your upper body towards the ground while keeping your back straight.", "Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.", "Repeat for the desired number of repetitions."]', '["Túmbate boca abajo sobre un banco plano con la cadera en el borde y los pies sujetos.", "Cruza los brazos sobre el pecho o colócalos detrás de la cabeza.", "Baja el torso hacia el suelo flexionando la cadera, con la espalda recta.", "Sube el torso hasta que quede alineado con las piernas.", "Repite el número de repeticiones deseado."]'),
  ('jalones tras nuca en polea', 'cable-wide-grip-rear-pulldown-behind-neck.gif', null::text, '["Sit at the pulldown machine and adjust the leg support.", "Grab the bar with a wide overhand grip.", "Tilt your head slightly forward.", "Pull the bar down behind your neck, squeezing your shoulder blades.", "Pause, then let the bar rise slowly.", "Repeat for the desired number of repetitions."]', '["Siéntate en la máquina de jalón y ajusta el soporte de las piernas.", "Sujeta la barra con un agarre prono amplio.", "Inclina ligeramente la cabeza hacia delante.", "Tira de la barra hacia abajo por detrás de la nuca, juntando los omóplatos.", "Haz una breve pausa y deja subir la barra lentamente.", "Repite el número de repeticiones deseado."]'),
  ('l-sit', 'l-sit-on-floor.gif', null::text, '["Sit on the floor with your legs extended in front of you.", "Place your hands on the floor beside your hips, fingers pointing forward.", "Engage your core and lift your legs off the ground, keeping them straight.", "Try to bring your legs parallel to the floor, forming an ''L'' shape with your body.", "Hold this position for as long as you can.", "Slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el suelo con las piernas extendidas al frente.", "Apoya las manos en el suelo junto a la cadera.", "Empuja con los brazos y despega cadera y piernas del suelo, con las piernas rectas.", "Mantén la forma de ''L'' el tiempo que puedas.", "Baja con control."]'),
  ('nordic curl (curl nórdico)', 'inverse-leg-curl-bench-support.gif', null::text, '["Kneel on the pad with your ankles secured under the support.", "Keep your body straight from knees to head.", "Slowly lean forward, using your hamstrings to control the descent.", "Lower as far as you can with control.", "Contract your hamstrings to return to the upright position.", "Repeat for the desired number of repetitions."]', '["Arrodíllate sobre la almohadilla con los tobillos sujetos bajo el soporte.", "Mantén el cuerpo recto desde las rodillas hasta la cabeza.", "Inclínate hacia delante lentamente, frenando la caída con los isquiotibiales.", "Baja lo más que puedas con control.", "Contrae los isquiotibiales para volver a la posición vertical.", "Repite el número de repeticiones deseado."]'),
  ('pallof press (prensa pallof)', 'band-horizontal-pallof-press.gif', null::text, '["Attach the band to a sturdy anchor point at waist height.", "Stand perpendicular to the anchor point with your feet shoulder-width apart.", "Grasp the band handle with both hands and step away from the anchor point to create tension in the band.", "Bring your hands to your chest, keeping your elbows bent and close to your body.", "Engage your core and maintain a stable stance.", "Extend your arms straight out in front of you, pushing the band away from your body.", "Hold the extended position for a few seconds, focusing on maintaining tension in your core.", "Slowly bring your hands back to your chest, resisting the pull of the band.", "Repeat for the desired number of repetitions."]', '["Ancla la banda a la altura del pecho.", "Ponte de lado al anclaje con los pies a la anchura de los hombros.", "Sujeta la banda con ambas manos junto al pecho y aléjate para tensarla.", "Activa el core y extiende los brazos al frente sin dejar que el torso gire.", "Mantén unos segundos y vuelve las manos al pecho.", "Repite el número de repeticiones deseado."]'),
  ('patada de glúteo en máquina', 'lever-hip-extension-v-2.gif', null::text, '["Position yourself on the machine with your torso on the pad and grab the handles.", "Place your working foot on the platform or roller.", "Push back and up, extending your hip.", "Squeeze your glute at the top, pause, then return slowly.", "Complete the repetitions, then switch legs."]', '["Colócate en la máquina con el torso apoyado en la almohadilla y sujeta los agarres.", "Apoya el pie de trabajo en la plataforma o rodillo.", "Empuja hacia atrás y hacia arriba extendiendo la cadera.", "Contrae el glúteo arriba, haz una breve pausa y vuelve lentamente.", "Completa las repeticiones y cambia de pierna."]'),
  ('patada de glúteo en polea (donkey kick)', 'cable-standing-hip-extension.gif', null::text, null::text, null::text),
  ('patada de tríceps (kickback)', 'dumbbell-kickback.gif', null::text, '["Place one hand and one knee on a bench, with your back straight and parallel to the floor.", "Hold a dumbbell in the other hand with your upper arm against your side and your elbow at 90 degrees.", "Keeping your upper arm still, extend your elbow back until your arm is straight.", "Squeeze your triceps, pause, then return slowly.", "Complete the repetitions, then switch arms."]', '["Apoya una mano y una rodilla en un banco, con la espalda recta y paralela al suelo.", "Sujeta una mancuerna con la otra mano y pega el brazo al cuerpo, con el codo a 90 grados.", "Sin mover el brazo, extiende el codo hacia atrás hasta que el brazo quede recto.", "Contrae el tríceps, haz una breve pausa y vuelve lentamente.", "Completa las repeticiones y cambia de brazo."]'),
  ('peso muerto con barra de trampa (hex bar dl)', 'trap-bar-deadlift.gif', null::text, '["Stand with your feet shoulder-width apart and the trap bar on the ground in front of you.", "Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip.", "Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees.", "As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement.", "Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement.", "Repeat for the desired number of repetitions."]', '["Colócate dentro de la barra hexagonal con los pies a la anchura de los hombros.", "Flexiona cadera y rodillas y sujeta las asas laterales.", "Con la espalda recta y el pecho arriba, levanta la barra extendiendo cadera y rodillas.", "Empuja con los talones y contrae los glúteos arriba.", "Baja la barra al suelo con control, manteniendo la espalda recta.", "Repite el número de repeticiones deseado."]'),
  ('peso muerto con cadena o banda', 'band-stiff-leg-deadlift.gif', 'Peso Muerto con Piernas Rígidas con Banda', null::text, null::text),
  ('peso muerto con piernas rígidas (stiff-leg)', 'barbell-straight-leg-deadlift.gif', null::text, '["Stand with your feet shoulder-width apart and your toes pointing forward.", "Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.", "Lower the barbell until you feel a stretch in your hamstrings.", "Engage your hamstrings and glutes to lift the barbell back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies a la anchura de los hombros.", "Sujeta la barra con agarre prono, un poco más abierto que los hombros.", "Flexiona la cadera y baja la barra hacia el suelo con la espalda recta y las rodillas casi extendidas.", "Baja hasta sentir el estiramiento en los isquiotibiales.", "Contrae glúteos e isquiotibiales para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('plancha', 'weighted-front-plank.gif', 'Plancha con Peso (Weighted Plank)', '["Lie face down with a weight plate placed on your back.", "Place your forearms on the floor with your elbows under your shoulders.", "Extend your legs and rest on your toes.", "Engage your core and lift your body off the floor, keeping it in a straight line.", "Hold the position for the prescribed time.", "Lower with control and remove the plate."]', '["Colócate boca abajo con un disco apoyado sobre la espalda.", "Apoya los antebrazos en el suelo con los codos bajo los hombros.", "Extiende las piernas y apoya la punta de los pies.", "Activa el core y despega el cuerpo del suelo, manteniéndolo en línea recta.", "Mantén la posición el tiempo indicado.", "Baja con control y retira el disco."]'),
  ('prensa de piernas unilateral', 'sled-45-degrees-one-leg-press.gif', null::text, '["Sit in the 45-degree leg press with your back against the pad.", "Place one foot in the middle of the platform.", "Release the safeties and bend your knee, lowering the platform with control.", "Push through your heel until your leg is extended.", "Complete the repetitions, then switch legs."]', '["Siéntate en la prensa de 45 grados con la espalda apoyada.", "Coloca un solo pie en el centro de la plataforma.", "Quita los seguros y flexiona la rodilla bajando la plataforma con control.", "Empuja con el talón hasta extender la pierna.", "Completa las repeticiones y cambia de pierna."]'),
  ('press arnold', 'dumbbell-arnold-press.gif', null::text, null::text, null::text),
  ('press de banca con mancuerna en rotación neutra', 'dumbbell-neutral-grip-bench-press.gif', null::text, '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest.", "Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.", "Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco plano con los pies apoyados en el suelo.", "Sujeta una mancuerna en cada mano con agarre neutro (palmas enfrentadas) y los brazos extendidos sobre el pecho.", "Baja las mancuernas hacia el pecho con los codos cerca del cuerpo.", "Haz una breve pausa y empuja hasta extender los brazos.", "Repite el número de repeticiones deseado."]'),
  ('press de hombro a 1 brazo', 'dumbbell-one-arm-shoulder-press.gif', null::text, '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.", "Press the dumbbell upward until your arm is fully extended overhead.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Ponte de pie con los pies a la anchura de los hombros.", "Sujeta una mancuerna a la altura del hombro con la palma hacia delante.", "Empuja la mancuerna hacia arriba hasta extender el brazo.", "Haz una breve pausa y baja lentamente al hombro.", "Completa las repeticiones y cambia de brazo."]'),
  ('press de hombro con agarre neutro', 'dumbbell-seated-shoulder-press-parallel-grip.gif', null::text, '["Sit on a bench with back support and a dumbbell in each hand.", "Hold the dumbbells at shoulder height with your palms facing each other.", "Press the dumbbells up until your arms are extended, without rotating your wrists.", "Pause at the top, then slowly lower them back to your shoulders.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con respaldo y una mancuerna en cada mano.", "Coloca las mancuernas a la altura de los hombros con las palmas enfrentadas.", "Empuja las mancuernas hacia arriba hasta extender los brazos, sin girar las muñecas.", "Haz una breve pausa arriba y baja lentamente a los hombros.", "Repite el número de repeticiones deseado."]'),
  ('press de hombro con mancuernas', 'dumbbell-seated-shoulder-press.gif', null::text, '["Sit on a bench with a dumbbell in each hand, resting on your thighs.", "Raise the dumbbells to shoulder height, palms facing forward.", "Press the dumbbells upward until your arms are fully extended overhead.", "Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con respaldo y una mancuerna en cada mano.", "Sube las mancuernas a la altura de los hombros con las palmas hacia delante.", "Empuja las mancuernas hacia arriba hasta extender los brazos.", "Haz una breve pausa arriba y baja lentamente a los hombros.", "Repite el número de repeticiones deseado."]'),
  ('press de hombros', 'barbell-seated-overhead-press.gif', null::text, '["Sit on a bench with your back straight and feet flat on the ground.", "Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.", "Press the barbell overhead by extending your arms fully.", "Pause for a moment at the top, then slowly lower the barbell back to shoulder level.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con la espalda recta y los pies apoyados en el suelo.", "Sujeta la barra con agarre prono, un poco más abierto que los hombros.", "Coloca la barra a la altura de los hombros, delante del cuello.", "Empuja la barra por encima de la cabeza hasta extender los brazos.", "Haz una breve pausa arriba y baja la barra a la altura de los hombros.", "Repite el número de repeticiones deseado."]'),
  ('press militar (por encima de la cabeza)', 'barbell-standing-close-grip-military-press.gif', null::text, '["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart.", "Lift the barbell to shoulder height, keeping your elbows close to your body.", "Press the barbell overhead, extending your arms fully.", "Lower the barbell back to shoulder height.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies a la anchura de los hombros.", "Sujeta la barra con agarre prono, un poco más cerrado que los hombros, a la altura de las clavículas.", "Empuja la barra por encima de la cabeza hasta extender los brazos.", "Baja la barra de nuevo a la altura de los hombros.", "Repite el número de repeticiones deseado."]'),
  ('remo con mancuerna a 1 mano (one-arm row)', 'dumbbell-one-arm-bent-over-row.gif', null::text, '["Place one hand and one knee on a bench, keeping your back straight.", "Hold a dumbbell in the other hand with your arm extended towards the floor.", "Pull the dumbbell towards your hip, keeping your elbow close to your body.", "Squeeze your shoulder blade at the top, pause, then lower slowly.", "Complete the repetitions, then switch sides."]', '["Apoya una mano y una rodilla en un banco, con la espalda recta.", "Sujeta una mancuerna con la otra mano, con el brazo extendido hacia el suelo.", "Tira de la mancuerna hacia la cadera, con el codo pegado al cuerpo.", "Junta el omóplato arriba, haz una breve pausa y baja lentamente.", "Completa las repeticiones y cambia de lado."]'),
  ('remo inclinado con barra (barbell row)', 'barbell-bent-over-row.gif', null::text, null::text, null::text),
  ('remo inclinado con barra en t (t-bar row)', 'lever-t-bar-row.gif', null::text, '["Stand on the platform of the T-bar row machine.", "Hinge forward with a straight back and slightly bent knees.", "Grab the handles with your arms extended.", "Pull the handles towards your abdomen, squeezing your shoulder blades.", "Pause, then lower slowly.", "Repeat for the desired number of repetitions."]', '["Colócate de pie sobre la plataforma de la máquina de remo en T.", "Inclina el torso hacia delante con la espalda recta y las rodillas ligeramente flexionadas.", "Sujeta los agarres con los brazos extendidos.", "Tira de los agarres hacia el abdomen juntando los omóplatos.", "Haz una breve pausa y baja lentamente.", "Repite el número de repeticiones deseado."]'),
  ('rodillo de muñeca (wrist roller)', 'wrist-roller.gif', null::text, '["Attach a weight to one end of a rope or bar.", "Hold the other end of the rope or bar with both hands, palms facing down.", "Stand with your feet shoulder-width apart and your arms fully extended in front of you.", "Slowly roll the weight up towards your hands by flexing your wrists.", "Pause for a moment at the top, then slowly lower the weight back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie y sujeta el rodillo con ambas manos, palmas hacia abajo y brazos extendidos al frente.", "Deja colgar la cuerda con el peso.", "Gira el rodillo con las muñecas para enrollar la cuerda y subir el peso.", "Cuando el peso llegue arriba, desenrolla lentamente para bajarlo.", "Repite el número de repeticiones deseado."]'),
  ('rueda abdominal (ab wheel rollout)', 'wheel-rollout.gif', null::text, '["Kneel on the floor and place the wheel roller in front of you.", "Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.", "Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.", "Continue rolling forward until your body is fully extended and your arms are overhead.", "Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.", "Repeat for the desired number of repetitions."]', '["Arrodíllate en el suelo y sujeta la rueda abdominal frente a ti.", "Con los brazos extendidos, activa el core.", "Rueda hacia delante lentamente estirando el cuerpo, sin arquear la espalda.", "Llega tan lejos como puedas manteniendo el control.", "Contrae el abdomen para volver rodando hacia las rodillas.", "Repite el número de repeticiones deseado."]'),
  ('saltos de tijera', 'astride-jumps-male.gif', null::text, '["Stand with your feet together and arms at your sides.", "Jump, spreading your legs and raising your arms out to the sides.", "Jump again to bring your legs together and lower your arms.", "Keep a steady rhythm and land softly.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies juntos y los brazos a los lados.", "Salta separando las piernas y elevando los brazos a los lados.", "Salta de nuevo para juntar las piernas y bajar los brazos.", "Mantén un ritmo constante y aterriza suave.", "Repite el número de repeticiones deseado."]'),
  ('sentadilla búlgara (búlgar split squat)', 'dumbbell-single-leg-split-squat.gif', null::text, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.", "Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground.", "Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Ponte de pie delante de un banco con una mancuerna en cada mano.", "Apoya el empeine del pie trasero sobre el banco y deja el pie delantero plano en el suelo.", "Flexiona la rodilla delantera y baja hasta que el muslo quede paralelo al suelo.", "Empuja con el talón delantero para volver arriba.", "Completa las repeticiones y cambia de pierna."]'),
  ('sentadilla con apoyo en pared (wall squat)', 'march-sit-wall.gif', 'Sentadilla en Pared con Elevación de Rodillas (Wall March)', '["Stand with your back against a wall and your feet hip-width apart.", "Slowly slide your back down the wall until your knees are bent at a 90-degree angle.", "Lift your right foot off the ground and bring your knee towards your chest.", "Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.", "Continue alternating between lifting your right and left foot for the desired number of repetitions."]', '["Apoya la espalda en una pared con los pies a la anchura de la cadera.", "Desliza la espalda hacia abajo hasta que las rodillas queden a 90 grados.", "Sin subir la cadera, levanta un pie y lleva la rodilla hacia el pecho.", "Bájalo y levanta el otro pie.", "Alterna las piernas hasta completar las repeticiones."]'),
  ('sentadilla con pierna adelantada (split squat)', 'split-squats.gif', null::text, '["Stand with your feet shoulder-width apart.", "Take a step forward with one foot and place it about two feet in front of the other foot.", "Lower your body by bending your knees and hips, keeping your back straight.", "Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.", "Pause for a moment, then push through your front heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Ponte de pie y da un paso largo al frente con una pierna.", "Mantén el torso erguido y el pie trasero apoyado en la punta.", "Flexiona ambas rodillas hasta que la rodilla trasera quede cerca del suelo.", "Empuja con el talón delantero para subir, sin mover los pies.", "Completa las repeticiones y cambia de pierna."]'),
  ('sentadilla en máquina hack', 'sled-hack-squat.gif', null::text, '["Adjust the sled machine to a comfortable position for your height.", "Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.", "Hold onto the handles or bars for stability.", "Lower your body by bending your knees and hips, keeping your back straight and chest up.", "Continue lowering until your thighs are parallel to the ground or slightly below.", "Pause for a moment, then push through your heels to raise your body back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Colócate en la máquina hack con la espalda y los hombros contra las almohadillas.", "Apoya los pies en la plataforma a la anchura de los hombros.", "Quita los seguros y flexiona las rodillas bajando con la espalda apoyada.", "Baja hasta que los muslos queden paralelos a la plataforma.", "Empuja con los talones para volver arriba.", "Repite el número de repeticiones deseado."]'),
  ('sentadilla trasera con barra alta', 'barbell-high-bar-squat.gif', null::text, '["Stand with your feet shoulder-width apart, toes slightly turned out.", "Place the barbell on your upper back, resting it on your traps.", "Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.", "Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.", "Drive through your heels to stand back up, extending your hips and knees.", "Repeat for the desired number of repetitions."]', '["Coloca la barra alta sobre los trapecios.", "Ponte de pie con los pies a la anchura de los hombros y las puntas ligeramente abiertas.", "Con el torso erguido, flexiona rodillas y cadera.", "Baja hasta que los muslos queden paralelos al suelo o lo más bajo que puedas.", "Empuja con los talones para subir.", "Repite el número de repeticiones deseado."]'),
  ('sentadilla trasera con barra baja', 'barbell-low-bar-squat.gif', null::text, '["Stand with your feet shoulder-width apart and the barbell resting on your upper back.", "Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back.", "Continue lowering until your thighs are parallel to the ground or slightly below.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca la barra baja sobre la espalda, por debajo de los trapecios.", "Ponte de pie con los pies a la anchura de los hombros.", "Con el pecho arriba, flexiona rodillas y cadera llevando la cadera hacia atrás.", "Baja hasta que los muslos queden paralelos al suelo o un poco más.", "Empuja con los talones para subir.", "Repite el número de repeticiones deseado."]'),
  ('thruster (sentadilla + press)', 'barbell-thruster.gif', null::text, '["Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip.", "Lower into a squat position by bending your knees and pushing your hips back.", "As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.", "Lower the barbell back to shoulder height as you lower back into the squat position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con la barra a la altura de los hombros, en agarre prono.", "Baja en sentadilla flexionando rodillas y cadera.", "Desde abajo, sube de forma explosiva y empuja la barra por encima de la cabeza en un solo movimiento.", "Baja la barra a los hombros mientras bajas a la siguiente sentadilla.", "Repite el número de repeticiones deseado."]'),
  ('tríceps con cuerda', 'cable-pushdown-with-rope-attachment.gif', null::text, '["Attach a rope attachment to a high pulley on a cable machine.", "Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.", "Grasp the rope with an overhand grip, palms facing each other.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Exhale and push the rope downward by extending your elbows until your arms are fully extended.", "Pause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex.", "Repeat for the desired number of repetitions."]', '["Engancha una cuerda en la polea alta.", "Ponte de pie frente a la máquina con los pies a la anchura de los hombros.", "Sujeta la cuerda con las palmas enfrentadas.", "Mantén los codos pegados al cuerpo y la parte superior de los brazos inmóvil.", "Empuja la cuerda hacia abajo hasta extender por completo los codos.", "Haz una breve pausa y vuelve lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('vuelos posteriores (deltoides posterior)', 'dumbbell-rear-lateral-raise.gif', null::text, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged.", "Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con una mancuerna en cada mano.", "Flexiona ligeramente las rodillas e inclina el torso hacia delante con la espalda recta.", "Con los codos ligeramente flexionados, eleva los brazos hacia los lados hasta que queden paralelos al suelo.", "Junta los omóplatos, haz una breve pausa y baja lentamente.", "Repite el número de repeticiones deseado."]'),
  ('zancada con giro de tronco', 'lunge-with-twist.gif', null::text, '["Start by standing with your feet shoulder-width apart.", "Take a step forward with your right foot, lowering your body into a lunge position.", "As you lunge, twist your torso to the right, bringing your left elbow towards your right knee.", "Pause for a moment, then return to the starting position.", "Repeat on the other side, stepping forward with your left foot and twisting your torso to the left.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie con los pies a la anchura de los hombros.", "Da un paso al frente y baja a posición de zancada.", "Abajo, gira el torso hacia el lado de la pierna adelantada.", "Vuelve al centro y empuja para regresar a la posición inicial.", "Alterna los lados hasta completar las repeticiones."]'),
  ('zancada con pausa en el punto bajo', 'barbell-lunge.gif', 'Zancada con Barra (Barbell Lunge)', null::text, null::text),
  ('zancada hacia atrás (reverse lunge)', 'barbell-rear-lunge.gif', null::text, '["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.", "Take a step backward with your right foot, landing on the ball of your foot.", "Bend both knees to lower your body until your left thigh is parallel to the ground.", "Push through your left heel to return to the starting position.", "Repeat with the other leg."]', '["Ponte de pie con los pies a la anchura de los hombros y la barra apoyada en la parte alta de la espalda.", "Da un paso hacia atrás con una pierna, apoyando la punta del pie.", "Flexiona ambas rodillas hasta que el muslo de la pierna delantera quede paralelo al suelo.", "Empuja con el talón delantero para volver a la posición inicial.", "Alterna las piernas hasta completar las repeticiones."]'),
  ('zancada lateral (side lunge)', 'barbell-lateral-lunge.gif', null::text, '["Stand with your feet shoulder-width apart, holding a barbell across your upper back.", "Take a big step to the side with your right foot, keeping your left foot planted.", "Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.", "Push off with your right foot and return to the starting position.", "Repeat on the other side, stepping with your left foot."]', '["Ponte de pie con la barra apoyada en la parte alta de la espalda.", "Da un paso amplio hacia un lado.", "Flexiona la rodilla de esa pierna y baja, con la otra pierna extendida.", "Empuja con el pie para volver al centro.", "Alterna los lados hasta completar las repeticiones."]')
) as v(old, file, new_name, en, es)
left join _copy_instr c on c.dst = v.old
where lower(e.name) = v.old;

-- 5) No exact GIF exists: no demo and no instructions that describe another movement.
update public.exercises set
  video_url = null, instructions_en = null, instructions_es = null, updated_at = now()
where lower(name) in (
  'curl de bíceps en suspensión (trx)',
  'curl de femoral con goma elástica',
  'curl de femoral con mancuerna (entre pies)',
  'dragon flag',
  'good morning con banda elástica',
  'hip thrust unilateral',
  'hiperextensiones en suelo (superman)',
  'patada de glúteo en 4 apoyos (fire hydrant)',
  'plancha con banda elástica',
  'press de banca unilateral',
  'saltos de gemelos (pliométricos)',
  'snatch (arrancada)',
  'suitcase carry (carga maletero)',
  'sujeción con pinza (plate pinch)',
  'zancada cruzada (curtsy lunge)'
);

-- 6) The point of all this: no GIF may be shared.
do $$
declare dup text;
begin
  select string_agg(video_url, ' | ') into dup
    from (select video_url from public.exercises
           where video_url is not null group by video_url having count(*) > 1) d;
  if dup is not null then
    raise exception 'GIF shared by more than one exercise: %', dup;
  end if;
end $$;

commit;

